    if (type === "right-30") body = `<g ${show(1,step)}><path d="M120 292V55L520 292Z" class="main"/><path d="M120 270h22v22" class="right"/><text x="101" y="46">A</text><text x="528" y="317">B</text><text x="95" y="317">C</text></g><g ${show(2,step)}><path d="M120 94A39 39 0 0 1 143 87" class="arc"/><text x="151" y="103" class="tag">30°</text><text x="277" y="155" class="tag">斜边 AB</text><text x="292" y="284" class="tag">30°角的对边 BC</text></g><g ${show(3,step)}><path d="M300 282v20" class="tick"/><path d="M302 169l14 11" class="tick"/><text x="310" y="232" text-anchor="middle" class="small">BC = ½AB</text></g><g ${show(4,step)}><rect x="127" y="318" width="366" height="30" rx="15" class="note"/><text x="310" y="339" text-anchor="middle" class="small">前提缺一不可：直角三角形 + 一个锐角30°</text></g>`;
    if (type === "shortest-reflection") body = `<g ${show(1,step)}><path d="M50 205H570" class="main"/><text x="545" y="194" class="tag">直线 l</text><circle cx="105" cy="65" r="7"/><circle cx="245" cy="105" r="7"/><text x="82" y="57">A</text><text x="251" y="99">B</text></g><g ${show(2,step)}><circle cx="245" cy="305" r="7" class="pink"/><text x="255" y="315">B′</text><path d="M245 105V305" class="measure"/><path d="M233 193v12h12" class="right"/><path d="M237 147h16M237 255h16" class="tick"/></g><g ${show(3,step)}><path d="M105 65L245 305" class="goal"/><circle cx="187" cy="205" r="7" fill="${C.gold}"/><text x="173" y="230">P</text><path d="M105 65L187 205L245 105" class="measure"/></g><g ${show(4,step)}><rect x="118" y="320" width="384" height="28" rx="14" class="note"/><text x="310" y="340" text-anchor="middle" class="small">PB=PB′，故PA+PB=PA+PB′；直线段最短</text></g>`;
